  process.stdout.write(headings(parsed.blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const rows = [
    ...[...fileDefinitions].map(([label, url]) => ({ label, url, source: 'file' })),
    ...[...parsed.definitions].map(([label, url]) => ({ label, url, source: 'document' })),
  ].sort((a, b) => (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
  process.stdout.write(rows.map(row => `${row.label} ${row.url} ${row.source}\n`).join(''))
  process.stdout.write(`total ${rows.length}\n`)
}
"}

